			},
			FilterName:   "http_simple_mutations",
			FilterConfig: cfg,
		}

		rustFilter := filters.MustNewStagedFilter(rustformationFilterNamePrefix,
			&rustCfg,
			filters.BeforeStage(filters.AcceptedStage),
		)
