	b, ok := other.(*retryIR)
	if !ok {
		return false
	}
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	return proto.Equal(a.policy, b.policy)
}

func (a *retryIR) Validate() error {
	if a == nil || a.policy == nil {
		return nil
	}
	return a.policy.Validate()
